    // Exact nb4_s5501 / nb4_s5508 farm snapshots; source SHA256s live in preset-source-manifest.json.
    // A single compressed pack shares repeated schema. These are complete DPSAVE records, not synthetic wallets.
    public static class V6nUiPresets
    {
        static readonly int[] Chapter = { 1, 2, 3 };
        static readonly double[] Play = { 1800, 3600, 7200 };
        public static SaveData Decode(int index, out string why)
        {
            why = null;
            if (index < 0 || index >= Chapter.Length) { why = "index"; return null; }
            try
            {
                byte[] zipped = Convert.FromBase64String(V6nUiPresetData.Pack);
                using var input = new MemoryStream(zipped);
                using var gzip = new GZipStream(input, CompressionMode.Decompress);
                using var output = new MemoryStream();
                gzip.CopyTo(output);
                string[] records = Encoding.UTF8.GetString(output.ToArray()).Split('\\0');
                if (records.Length != 3) { why = "record count"; return null; }
                var data = SaveDisk.Parse(Encoding.UTF8.GetBytes(records[index]), out why, out _);
                if (data == null) return null;
                var core = data.Part(OnePitSave.SaveKey);
                if (core == null || JsonUtility.FromJson<CoreCheck>(core.Json).Chapter != Chapter[index]
                    || Math.Abs(data.PlaySeconds - Play[index]) > 1 || data.State == null
                    || double.IsNaN(data.State.Money) || data.State.Money < 0)
                { why = "snapshot invariants"; return null; }
                return data;
            }
            catch (Exception e) { why = e.GetType().Name; return null; }
        }

        [Serializable] sealed class CoreCheck { public int Chapter; }

        public static bool Apply(int index)
        {
            if (!DevTools.PlaytestEnabled || Game.Ads == null || Game.Ads.Busy || HallAway.Pending
                || !(Game.Save is SaveStore store)) return false;
            var data = Decode(index, out string why);
            if (data == null) { Debug.LogError("[PITT] preset rejected: " + why); return false; }
            // Rebase wall clocks only. Gameplay clocks, balances, circle IDs, levels and RNG stay as captured.
            long ticks = DateTime.UtcNow.Ticks;
            double unix = new DateTimeOffset(new DateTime(ticks, DateTimeKind.Utc)).ToUnixTimeMilliseconds() / 1000.0;
            data.SavedUtcTicks = ticks;
            foreach (var p in data.Parts)
                if (p != null && (p.Key​ == "op.away" || p.Key​ == "op.grem"))
                    p.Json = Regex.Replace(p.Json, "\\\\"Unix\\\\":-?[0-9]+(?:\\\\.[0-9]+)?",
                        "\\\\"Unix\\\\":" + unix.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture));
            return store.ImportV6nSnapshot(SaveDisk.Encode(data), "v6n:" + index);
        }
    }
}
