            _disk.Load(out long diskSeq);
            data.Seq = System.Math.Max(_seq, diskSeq) + 1;
            data.SavedUtcTicks = System.DateTime.UtcNow.Ticks;
            data.Reason = preset;
            if (!_disk.Write(data)) return false;
            // Live old-world snapshots must not overwrite the imported A/B record during IDBFS flush/navigation.
            _seq = data.Seq;
            ClearPending(); _snapPending = false; _sealed = true;
            Pitt.GameFlow.ModeSelect.Relaunch("-pittMode big -pittResume", "dev:preset");
            return true;
        }
    }
}
